// Правец-8А (болгарский и для СССР): клавиатура на токопроводящей резине (плата Е37.102.026,
// микро-ЭВМ СМ650), латиница QWERTY, кириллица фонетическая (ЯВЕРТЪ).
//
// Клавиша хоста[/модификаторы]: код. S - Shift, R - кириллица (C/L Lock),
// 8 - 8-битная кодовая таблица (MODE1). Коды 7-битной таблицы - со стробом в
// разряде 7, как их читает $C000 (книга П. Петрова, табл. 2.1, П8.1-П8.4).
// В 8-битной таблице буква без Shift и без Caps Lock - строчная: код - $80
// (латиница $40-$5F, кириллица $60-$7F); это правило клавиатуры, его здесь
// не пишут. Запись с 8 отдается как есть. Код 0 - клавиша ничего не дает.
//
// C/L Lock - F10, Caps Lock - Caps Lock, F1/F2 - F1/F2, RESET - F12 (только с Ctrl).

// Буквы, латиница
A: $C1
B: $C2
C: $C3
D: $C4
E: $C5
F: $C6
G: $C7
H: $C8
I: $C9
J: $CA
K: $CB
L: $CC
M: $CD
N: $CE
O: $CF
P: $D0
Q: $D1
R: $D2
S: $D3
T: $D4
U: $D5
V: $D6
W: $D7
X: $D8
Y: $D9
Z: $DA

// Буквы, кириллица фонетическая (ЯВЕРТЪ): табл. П8.1 и П8.2 книги, у буквы
// кириллицы код ее латинской клавиши + $20
Q/R: $F1            // Я
W/R: $F7            // В
E/R: $E5            // Е
R/R: $F2            // Р
T/R: $F4            // Т
Y/R: $F9            // Ъ
U/R: $F5            // У
I/R: $E9            // И
O/R: $EF            // О
P/R: $F0            // П
[/R: $FB            // Ш
{/SR: $FB
]/R: $FD            // Щ
}/SR: $FD
\/R: $FC           // Э
bar/SR: $FC
~/R: $E0            // Ю
tilde/SR: $E0
A/R: $E1            // А
S/R: $F3            // С
D/R: $E4            // Д
F/R: $E6            // Ф
G/R: $E7            // Г
H/R: $E8            // Х
J/R: $EA            // Й
K/R: $EB            // К
L/R: $EC            // Л
=/R: $FE            // Ч
+/SR: $FE
Z/R: $FA            // З
X/R: $F8            // Ь
C/R: $E3            // Ц
V/R: $F6            // Ж
B/R: $E2            // Б
N/R: $EE            // Н
M/R: $ED            // М

// Цифры и знаки
0: $B0
1: $B1
2: $B2
3: $B3
4: $B4
5: $B5
6: $B6
7: $B7
8: $B8
9: $B9
!/S: $A1
@/S: $C0
#/S: $A3
$/S: $A4
%/S: $A5
^/S: $DE
&/S: $A6
*/S: $AA
(/S: $A8
)/S: $A9
-: $AD
_/S: $DF
=: $BD
+/S: $AB
semicolon: $BB
colon/S: $BA
': $A7
"/S: $A2
,: $AC
</S: $BC
.: $AE
>/S: $BE
slash: $AF
?/S: $BF

// Скобки: в 8-битной таблице без Shift - строчные { | } ~ `
[: $DB
{/S: $DB
{/S8: $5B
]: $DD
}/S: $DD
}/S8: $5D
\: $DC
bar/S: $DC
bar/S8: $5C
tilde/S: $DE
tilde/S8: $5E
~: $C0
~/8: $40

// Управляющие
space: $A0
ret: $8D
enter: $8D
esc: $9B
tab: $89
back: $88
left: $88
right: $95
up: $8B
down: $8A
del: $FF
